def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(size, separators):
        result = []
        start = 0
        for s in separators + [size]:
            if start < s:
                result.append((start, s))
            start = s + 1
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)
    cells = {}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            colors = {grid[r][c] for r in range(r0, r1)
                      for c in range(c0, c1) if grid[r][c] in (2, 3)}
            if colors:
                cells[i, j] = next(iter(colors))

    painted = {}
    for color in (2, 3):
        points = [p for p, value in cells.items() if value == color]
        for a in range(len(points)):
            r1, c1 = points[a]
            for b in range(a + 1, len(points)):
                r2, c2 = points[b]
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted.setdefault((r1, c), set()).add(color)
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted.setdefault((r, c1), set()).add(color)

    out = [row[:] for row in grid]
    for (i, j), colors in painted.items():
        value = 6 if len(colors) > 1 else next(iter(colors))
        r0, r1 = rb[i]
        c0, c1 = cb[j]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = value
    return out
